// Simulated DB interface
namespace db {
    std::string last_query;
    void execute(const std::string& query) {
        last_query = query;
        // In production, this executes against PostgreSQL
    }
}

static std::atomic<bool> g_shutdown_requested{false};
static std::mutex g_container_mutex;

class QueryBuilder {
public:
    enum class EscapeMode { Full, IdentifierOnly, None };

    static std::string escape_literal(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 2);
        for (char c : input) {
            if (c == '\'') result += "''";
            else if (c == '\\') result += "\\\\";
            else if (c == '\0') continue;
            else result += c;
        }
        return result;
    }

    static std::string escape_identifier(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 2);
        for (char c : input) {
            if (c == '"') result += "\"\"";
            else if (c == '\0') continue;
            else result += c;
        }
        return result;
    }

    static std::string build_update(const std::string& table,
                                     const std::map<std::string, std::string>& fields,
                                     const std::string& where_clause) {
        std::ostringstream oss;
        oss << "UPDATE \"" << escape_identifier(table) << "\" SET ";
        bool first = true;
        for (auto& [k, v] : fields) {
            if (!first) oss << ", ";
            oss << "\"" << escape_identifier(k) << "\" = '" << escape_literal(v) << "'";
            first = false;
        }
        oss << " WHERE " << where_clause;
        return oss.str();
    }
};

class ContainerState {
public:
    std::string container_id;
    std::string status;
    std::string node_affinity;
    int restart_count = 0;

    std::string get_status_filter() const {
        // Build a WHERE clause for this container's status updates
        return "container_id = '" + QueryBuilder::escape_literal(container_id) + "'";
    }
};

class ShutdownCoordinator {
    std::vector<ContainerState> active_containers_;
    std::function<void(const ContainerState&)> drain_callback_;

public:
    void register_drain_callback(std::function<void(const ContainerState&)> cb) {
        drain_callback_ = cb;
    }

    void add_container(const ContainerState& cs) {
        std::lock_guard<std::mutex> lock(g_container_mutex);
        active_containers_.push_back(cs);
    }

    void drain_all() {
        std::lock_guard<std::mutex> lock(g_container_mutex);
        for (auto& container : active_containers_) {
            if (drain_callback_) drain_callback_(container);
        }
        active_containers_.clear();
    }
};

class Orchestrator {
    ShutdownCoordinator coordinator_;

    void persist_status_change(const ContainerState& cs, const std::string& new_status) {
        std::map<std::string, std::string> updates;
        updates["status"] = new_status;
        updates["node"] = cs.node_affinity;

        std::string query = QueryBuilder::build_update(
            "containers", updates, cs.get_status_filter());
        db::execute(query);
    }

    void on_graceful_drain(const ContainerState& cs) {
        persist_status_change(cs, "draining");
    }

public:
    Orchestrator() {
        coordinator_.register_drain_callback(
            [this](const ContainerState& cs) { on_graceful_drain(cs); });
    }

    void schedule_container(const std::string& id, const std::string& node) {
        ContainerState cs;
        cs.container_id = id;
        cs.status = "running";
        cs.node_affinity = node;
        coordinator_.add_container(cs);

        std::map<std::string, std::string> fields;
        fields["status"] = "running";
        fields["node"] = node;
        std::string where = cs.get_status_filter();
        db::execute(QueryBuilder::build_update("containers", fields, where));
    }

    void initiate_shutdown() {
        g_shutdown_requested.store(true);
        coordinator_.drain_all();
    }

    // Admin API: reschedule container to new node
    void reschedule(const std::string& container_id, const std::string& target_node) {
        std::lock_guard<std::mutex> lock(g_container_mutex);
        // target_node goes through build_update which escapes SET values
        // container_id goes through get_status_filter which escapes in WHERE
        std::map<std::string, std::string> fields;
        fields["node"] = target_node;
        fields["status"] = "migrating";

        ContainerState cs;
        cs.container_id = container_id;
        std::string query = QueryBuilder::build_update(
            "containers", fields, cs.get_status_filter());
        db::execute(query);
    }

    // Health check endpoint: filter by node
    void health_check_by_node(const std::string& node_name) {
        // Uses literal escaping for the node filter value
        std::string query = "SELECT * FROM containers WHERE node = '"
            + QueryBuilder::escape_literal(node_name) + "'";
        db::execute(query);
    }
};

void signal_handler(int sig) {
    g_shutdown_requested.store(true);
}

int main() {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    Orchestrator orch;
    orch.schedule_container("abc-123", "node-1");
    orch.schedule_container("def-456", "node-2");

    // Simulate admin API call
    orch.reschedule("abc-123", "node-3");

    // Simulate health check
    orch.health_check_by_node("node-1");

    if (g_shutdown_requested.load()) {
        orch.initiate_shutdown();
    }

    return 0;
}
